<?php
declare(strict_types=1);require_once __DIR__.'/SourceCatalog.php';header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: default-src 'none'; img-src 'self'; style-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'self'");header('Referrer-Policy: no-referrer');
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function param(string $key,string $default=''):string{$v=$_GET[$key]??$default;if(!is_string($v)||strlen($v)>256)throw new InvalidArgumentException('Invalid request');return$v;}
function url(array $args):string{return'index.php?'.e(http_build_query($args));}
function photo(?string $id,string $name,string $class='portrait'):string{return$id?'<img class="'.e($class).'" src="api.php?action=media&amp;id='.e($id).'" alt="'.e($name).'" loading="lazy" decoding="async">':'<div class="no-photo">الصورة غير متاحة</div>';}
try{$c=new HuroofSourceCatalog(dirname(__DIR__,2));$league=param('league');$club=param('club');$q=param('q');$id=param('player');$page=param('page','1');if(!preg_match('/^[0-9]+$/D',$page))throw new InvalidArgumentException('Invalid page');$clubs=$c->clubs($league);$detail=$id?$c->player($id):null;$team=$club?$c->club($club):null;$results=($q!==''||$team)?$c->players($q,$club,$league,(int)$page):null;}
catch(Throwable $x){http_response_code($x instanceof InvalidArgumentException?400:503);echo'<!doctype html><html dir="rtl" lang="ar"><meta charset="utf-8"><p>تعذر فتح الطلب. تحقق من المدخلات والملفات المحلية.</p><a href="index.php">المكتبة</a></html>';exit;}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>حروف الكورة | المكتبة</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.php"><span class="mark">ح</span><span>حروف الكورة<small>HUROOF ALKORA · المكتبة</small></span></a><span>2026–2027</span></header><main><div class="notice"><strong>بيانات المصادر قيد المراجعة</strong><p>بطاقات المصدر لا تعني هويات نهائية مستقلة. الصور والبيانات غير معتمدة تلقائيًا للأسئلة.</p></div><nav><a href="index.php">جميع الدوريات</a><?php foreach($c->leagues()as$l):?><a class="<?= $league===$l['id']?'selected':'' ?>" href="<?= url(['league'=>$l['id']]) ?>"><?= e($l['nameAr']) ?></a><?php endforeach;?></nav><form method="get"><input type="hidden" name="league" value="<?= e($league) ?>"><input type="hidden" name="club" value="<?= e($club) ?>"><label for="q">ابحث عن لاعب أو نادٍ أو جنسية أو مركز</label><div class="search"><input id="q" name="q" value="<?= e($q) ?>" maxlength="128" placeholder="الاسم العربي أو الإنجليزي"><button>بحث</button></div></form>
<?php if($detail):$p=$detail['player'];?><a href="<?= url(['club'=>$detail['club']['id']]) ?>">← العودة للنادي</a><article class="detail"><div><?= photo($p['photo'],$p['name']) ?><small>الصورة قيد مراجعة الهوية والقميص والحقوق</small></div><section><p class="muted"><?= e($detail['club']['nameAr']?:$detail['club']['name']) ?></p><h1><bdi><?= e($p['nameAr']??$p['name']) ?></bdi></h1><p><bdi><?= e($p['name']) ?></bdi></p><dl><?php foreach(['dateOfBirth'=>'تاريخ الميلاد','nationality'=>'الجنسية كما في المصدر','position'=>'المركز','shirtNumber'=>'رقم القميص','heightCm'=>'الطول بالسنتيمتر','weightKg'=>'الوزن بالكيلوغرام','preferredFoot'=>'القدم المفضلة','birthPlace'=>'مكان الميلاد','joinedClubAsPublished'=>'الانضمام كما في المصدر']as$key=>$label):?><div><dt><?= e($label) ?></dt><dd><bdi><?= e($p[$key]??'غير متاح') ?></bdi></dd></div><?php endforeach;?></dl><p class="muted">المسيرة والانتقالات والإحصائيات الكاملة لم تُربط بهذه البطاقة بعد.</p><?php if(preg_match('~^https://~',$p['source'])):?><a href="<?= e($p['source']) ?>" target="_blank" rel="noopener noreferrer">فتح المصدر ↗</a><?php endif;?></section></article>
<?php elseif($results):?><?php if($team):?><div class="team"><?= photo($team['logo'],$team['name'],'logo') ?><h1><bdi><?= e($team['nameAr']?:$team['name']) ?></bdi></h1></div><?php foreach($team['coaches']as$coach):?><div class="coach"><?php if(!empty($coach['photo'])):?><?= photo($coach['photo'],$coach['name'],'coach-photo') ?><?php endif;?><strong>المدرب المذكور في المصدر: </strong><bdi><?= e($coach['nameAr']??$coach['name']) ?></bdi><small> · الفترة والهوية قيد المراجعة</small></div><?php endforeach;?><?php if(!empty($team['coachReviewNote'])):?><p class="notice"><?= e($team['coachReviewNote']) ?></p><?php endif;?><?php endif;?><h2><?= $results['total'] ?> بطاقة مصدر</h2><div class="grid players"><?php foreach($results['items']as$p):?><a class="card" href="<?= url(['player'=>$p['id']]) ?>"><?= photo($p['photo'],$p['name']) ?><div class="text"><small><?= e($p['clubName']) ?></small><h3><bdi><?= e($p['nameAr']??$p['name']) ?></bdi></h3><p><bdi><?= e($p['position']??'المركز غير متاح') ?></bdi></p><span class="tag">قيد المراجعة</span></div></a><?php endforeach;?></div><div class="pages"><?php if($results['page']>1):?><a href="<?= url(['club'=>$club,'league'=>$league,'q'=>$q,'page'=>$results['page']-1]) ?>">السابق</a><?php endif;?><span>صفحة <?= $results['page'] ?> من <?= max(1,(int)ceil($results['total']/24)) ?></span><?php if($results['page']*24<$results['total']):?><a href="<?= url(['club'=>$club,'league'=>$league,'q'=>$q,'page'=>$results['page']+1]) ?>">التالي</a><?php endif;?></div>
<?php else:?><h1>مكتبة الفرق</h1><p class="muted"><?= count($clubs) ?> ناديًا من المصادر المجموعة</p><div class="grid clubs"><?php foreach($clubs as$t):?><a class="card club" href="<?= url(['league'=>$t['league'],'club'=>$t['id']]) ?>"><?= photo($t['logo'],$t['name'],'logo') ?><h3><bdi><?= e($t['nameAr']?:$t['name']) ?></bdi></h3><p><?= $t['players'] ?> لاعبًا في المصدر</p></a><?php endforeach;?></div><?php endif;?><footer>مكتبة حروف الكورة · الصور محلية، وحالة المراجعة ظاهرة.</footer></main></body></html>
